const cache = new Map();
const user = { id: "u1" };
cache.set(user, { lastLogin: Date.now() });
console.log(cache.get(user)); // hit by reference
console.log(cache.get({ id: "u1" })); // miss — different object

for (const [key, val] of cache) {
  console.log(key.id, val.lastLogin);
}

